begin;create temp table audit_runs(like public.sasi_durable_runs including all);create temp table audit_jobs(like public.sasi_durable_jobs including all);create or replace function pg_temp.audit_claim(
 p_worker_id text,p_lease_seconds integer default 75
) returns jsonb
language plpgsql security definer set search_path=public as $$
declare r pg_temp.audit_jobs%rowtype;
begin
 -- A crashed worker must not leave the task running forever. Do not repeat
 -- a provider submission whose outcome is unknown after losing the lease.
 with abandoned as (
  update pg_temp.audit_jobs set
   state='failed',error_code='WORKER_LEASE_EXPIRED_REVIEW_REQUIRED',
   lease_owner=null,lease_until=null,updated_at=now()
  where state='running' and lease_until is not null and lease_until<=now()
  returning run_id
 )
 update pg_temp.audit_runs set
  state='failed',error_code='WORKER_LEASE_EXPIRED_REVIEW_REQUIRED',updated_at=now()
 where id in(select run_id from abandoned) and state not in('succeeded','cancelled');

 update pg_temp.audit_jobs set
  state='failed',error_code='DEADLINE_EXPIRED',lease_owner=null,lease_until=null,updated_at=now()
 where state in('queued','waiting')
   and deadline_at is not null and deadline_at <= now();

 select * into r from pg_temp.audit_jobs
 where state in('queued','waiting')
   and available_at<=now()
   and (deadline_at is null or deadline_at>now())
   and (lease_until is null or lease_until<=now())
 order by
   (priority + least(9,floor(extract(epoch from(now()-created_at))/300)::int)) desc,
   available_at asc,created_at asc
 for update skip locked
 limit 1;

 if not found then return jsonb_build_object('ok',true,'claimed',false); end if;

 update pg_temp.audit_jobs set
  state='running',
  attempt=attempt+1,
  lease_owner=left(coalesce(p_worker_id,'worker'),160),
  lease_until=now()+make_interval(secs=>greatest(30,least(180,p_lease_seconds))),
  updated_at=now()
 where id=r.id returning * into r;

 return jsonb_build_object(
  'ok',true,'claimed',true,'id',r.id,'run_id',r.run_id,'user_id',r.user_id,
  'job_kind',r.job_kind,'workflow_version',r.workflow_version,'payload_json',r.payload_json,
  'attempt',r.attempt,'max_attempts',r.max_attempts,'lease_until',r.lease_until
 );
end $$;
do $test$ declare u uuid:=gen_random_uuid(); old_run uuid:=gen_random_uuid(); next_run uuid:=gen_random_uuid(); old_job uuid:=gen_random_uuid(); next_job uuid:=gen_random_uuid(); x jsonb; s text; attempts integer; begin
insert into audit_runs(id,user_id,session_key,task,idempotency_key,input_hash,state) values(old_run,u,'audit','text','old-key','hash','running'),(next_run,u,'audit','text','next-key','hash','created');
insert into audit_jobs(id,run_id,user_id,job_kind,workflow_version,payload_json,state,attempt,lease_owner,lease_until) values(old_job,old_run,u,'text','audit','{}','running',1,'crashed',now()-interval '1 minute'),(next_job,next_run,u,'text','audit','{}','queued',0,null,null);
x:=pg_temp.audit_claim('healthy-worker',75); if not (x->>'claimed')::boolean or (x->>'id')::uuid<>next_job then raise exception 'ready job not claimed';end if;
select state,attempt into s,attempts from audit_jobs where id=old_job;if s<>'failed' or attempts<>1 then raise exception 'abandoned submission retried or remains running';end if;
select state into s from audit_runs where id=old_run;if s<>'failed' then raise exception 'public run remains running';end if;
x:=pg_temp.audit_claim('second-worker',75);if (x->>'claimed')::boolean then raise exception 'duplicate live job claimed';end if;
end $test$;rollback;
